101    void returnBook(int id) {
102
103        issue.put(101, "A Good Book");
104        
105        if (issue.containsKey(id)) {
106            System.out.println("enter a book to return");
107            String bookName = input.nextLine();
108           
109            //get book id
110            int bookId = 0;
111            // iterate each entry of hashmap
112            for (Entry<Integer, String> entry : b1.book.entrySet()) {
113
114                // if give value is equal to value from entry
115                // print the corresponding key
116                if (entry.getValue().equals(bookName)) {
117                    bookId = entry.getKey();
118                    break;
119                }
120            }
121
122            // check if book is issued
123            if (issue.containsValue(bookName)) {
124
125                // remove issue record form issue HashMap
126                issue.remove(id);
127
128                // add book back to book hashmap
129                b1.book.put(bookId, bookName);
130
131                // print name of student and book
132                // get student name from id
133                String name = s1.student.get(id);
134                System.out.println("Name: " + name);
135                System.out.println("Book: " + bookName);
136                System.out.println("Book returned");
137
138            }
139
140            else {
141                System.out.println("Book is not issued.");
142            }
143
144        } else {
145            System.out.println("You haven't issued any book");
146        }
147    }
